package com.hrflow.exception; import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*; @RestControllerAdvice public class GlobalExceptionHandler{@ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<?> validation(MethodArgumentNotValidException e){Map<String,Object> m=new LinkedHashMap<>();m.put("timestamp",Instant.now());m.put("status",400);m.put("error","Validation failed");m.put("message",e.getBindingResult().getFieldErrors().stream().map(x->x.getField()+": "+x.getDefaultMessage()).toList());return ResponseEntity.badRequest().body(m);}@ExceptionHandler(NoSuchElementException.class)ResponseEntity<?> notFound(){return ResponseEntity.status(404).body(Map.of("status",404,"error","Not found"));}@ExceptionHandler(Exception.class)ResponseEntity<?> other(Exception e){return ResponseEntity.status(400).body(Map.of("status",400,"error","Request failed","message",e.getMessage()==null?"Unexpected error":e.getMessage()));}}
